import { Component, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ContactService } from '@core/services/contact.service';

@Component({
  selector: 'app-contatti',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './contatti.component.html',
  styleUrl: './contatti.component.scss',
})
export class ContattiComponent {
  form = {
    nome: '',
    email: '',
    oggetto: '',
    messaggio: '',
  };

  formStatus = signal<any>(null);
  isLoading = signal(false);

  constructor(private contactService: ContactService) {}

  onSubmit() {
    if (this.form.nome && this.form.email && this.form.messaggio && this.form.oggetto) {
      this.isLoading.set(true);

      this.contactService.sendMessage(this.form).subscribe({
        next: (response) => {
          this.isLoading.set(false);
          this.formStatus.set({
            success: true,
            message: response.message || 'Messaggio inviato con successo!',
          });
          this.form = { nome: '', email: '', oggetto: '', messaggio: '' };
          setTimeout(() => this.formStatus.set(null), 5000);
        },
        error: (error) => {
          this.isLoading.set(false);
          this.formStatus.set({
            success: false,
            message: 'Errore nell\'invio del messaggio. Riprova più tardi.',
          });
          setTimeout(() => this.formStatus.set(null), 5000);
        },
      });
    }
  }
}
<section id="contatti" class="contact-section">
  <div class="section-header">
    <span class="section-tag">Capitolo VI</span>
    <h2 class="section-title">Contatti</h2>
    <p class="section-subtitle">Per ricerche, conferenze, collaborazioni</p>
  </div>

  <div class="contact-container">
    <div class="contact-info">
      <div class="info-item">
        <div class="info-icon"><i class="fa-solid fa-envelope"></i></div>
        <div>
          <h4>Email</h4>
          <a href="mailto:pualin.zefi&#64;lezha-historia.al">pualin.zefi&#64;lezha-historia.al</a>
        </div>
      </div>
      <div class="info-item">
        <div class="info-icon"><i class="fa-solid fa-location-dot"></i></div>
        <div>
          <h4>Lezha, Albania</h4>
          <span>Sotto le mura del Castello di Lezha</span>
        </div>
      </div>
      <div class="info-item">
        <div class="info-icon"><i class="fa-brands fa-whatsapp"></i></div>
        <div>
          <h4>WhatsApp</h4>
          <a href="https://wa.me/355000000000" target="_blank" rel="noopener">+355 (00) 000 000</a>
        </div>
      </div>
      <div class="social-links">
        <a href="#" aria-label="Facebook"><i class="fa-brands fa-facebook-f"></i></a>
        <a href="#" aria-label="Instagram"><i class="fa-brands fa-instagram"></i></a>
        <a href="#" aria-label="LinkedIn"><i class="fa-brands fa-linkedin-in"></i></a>
        <a href="#" aria-label="YouTube"><i class="fa-brands fa-youtube"></i></a>
      </div>

      <div class="map-wrap">
        <iframe
          src="https://www.openstreetmap.org/export/embed.html?bbox=19.62%2C41.77%2C19.69%2C41.80&amp;layer=mapnik&amp;marker=41.7836%2C19.6447"
          loading="lazy"
          title="Mappa di Lezha"></iframe>
      </div>
    </div>

    <form class="contact-form" (ngSubmit)="onSubmit()">
      <h3 class="form-title">Scrivimi un messaggio</h3>
      <p class="form-subtitle">Risponderò personalmente a ogni richiesta.</p>

      <div class="form-row">
        <div class="form-group">
          <label for="nome">Nome</label>
          <input type="text" id="nome" [(ngModel)]="form.nome" name="nome" required placeholder="Il tuo nome">
        </div>
        <div class="form-group">
          <label for="email">Email</label>
          <input type="email" id="email" [(ngModel)]="form.email" name="email" required placeholder="email@dominio.it">
        </div>
      </div>

      <div class="form-group">
        <label for="oggetto">Oggetto</label>
        <input type="text" id="oggetto" [(ngModel)]="form.oggetto" name="oggetto" required placeholder="Motivo del contatto">
      </div>

      <div class="form-group">
        <label for="messaggio">Messaggio</label>
        <textarea id="messaggio" [(ngModel)]="form.messaggio" name="messaggio" rows="6" required placeholder="Scrivi qui il tuo messaggio..."></textarea>
      </div>

      <button type="submit" class="btn btn-primary form-submit">
        <span>Invia messaggio</span>
        <i class="fa-solid fa-paper-plane"></i>
      </button>

      <div class="form-status" *ngIf="formStatus" [class.success]="formStatus.success">
        {{ formStatus.message }}
      </div>
    </form>
  </div>
</section>
